 * @param {Array<{weight:number}>} ballots
 * @returns {number} sum of weights, treating a missing weight as 1.
 */
function _sumBallotWeights(ballots) {
  return ballots.reduce((sum, b) => sum + (b.weight || 1), 0);
}

