  module.exports = {
    runRankedChoiceVoting: runRankedChoiceVoting,
    breakTie: breakTie,
    countTieWinners: countTieWinners,
    _isRankedValue: _isRankedValue,
    _sumBallotWeights: _sumBallotWeights,
  };
}

