  const incomingEdges = Array(n).fill(0);
  const outgoingEdges = Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (locked[i][j]) {
        outgoingEdges[i]++;
        incomingEdges[j]++;
      }
    }
  }

