  const result = RCV.runRankedChoiceVoting(candidateNames, ballots, null);
  const aRow = result.summary.find((row) => row[0] === 'A');
  assert.equal(aRow[1], 'Eliminated');
  assert.equal(aRow[4], 'fewest second choice votes');
