function testUnrankedCandidateCannotWinCondorcetMethods() {
  const { Condorcet } = loadVotingAlgorithms();
  const candidateNames = ['A', 'B', 'C'];
  const ballots = makeBallots(candidateNames, [
    [1, 2, ''],
